        raise TypeError("value must be a string")
    if value == "":
        raise ValueError("value must not be empty")
    return value.upper()


def _value_for(ch: str, numerals: Dict[str, int]) -> int:
    if ch not in numerals:
        raise ValueError("invalid Roman numeral character")
    return numerals[ch]


